-- Detailed teaching revenue, ruble-precise appropriations, and event-backed regional requests.
-- Existing voting engines and the registration / three-reading budget workflow are preserved.
-- Monetary fields remain MILLION RUBLES; eight decimals preserve a kopeck.
alter table public.budget_transfer_requests
 add column event_case_id uuid,
 add column expected_result text;
create unique index event_cases_id_game_budget_idx on public.event_cases(id,game_id);
alter table public.budget_transfer_requests add constraint budget_transfer_event_game_fkey
 foreign key(event_case_id,game_id) references public.event_cases(id,game_id);
create index budget_transfer_event_game_idx on public.budget_transfer_requests(event_case_id,game_id);
create unique index budget_transfer_event_region_once_idx
 on public.budget_transfer_requests(game_id,event_case_id,region_code) where event_case_id is not null;
alter table public.budget_transfer_requests add constraint budget_transfer_event_result_check
 check(event_case_id is null or length(trim(coalesce(expected_result,''))) between 10 and 4000);

create function private.active_budget_actor(p_game uuid) returns boolean
language sql stable security definer set search_path=public,private,pg_temp as $$
 select auth.uid() is not null
 and exists(select 1 from games where id=p_game and status not in ('finished','archived'))
 and (private.is_platform_admin() or exists(
  select 1 from game_members m where m.game_id=p_game and m.user_id=auth.uid()
  and m.roster_archived_at is null and m.kind in ('teacher','student')
  and (m.kind='teacher' or private.role_is_available(p_game,m.user_id))));
$$;
create function private.lock_budget_actor(p_game uuid) returns void
language plpgsql security definer set search_path=public,private,pg_temp as $$
declare gs text;
begin
 select status into gs from games where id=p_game for no key update;
 if not found or gs in ('finished','archived') then raise exception 'Завершённая или архивная игра доступна только для просмотра бюджета.';end if;
 if auth.uid() is null then raise exception 'Требуется действующий участник игры.';end if;
 if not private.is_platform_admin() then
  perform 1 from game_members m where m.game_id=p_game and m.user_id=auth.uid()
   and m.roster_archived_at is null and m.kind in ('teacher','student')
   and (m.kind='teacher' or private.role_is_available(p_game,m.user_id)) for update;
  if not found then raise exception 'Требуется действующий участник этой игры.';end if;
 end if;
end;$$;
create or replace function private.can_prepare_budget(p_game uuid) returns boolean
language sql stable security definer set search_path=public,private,pg_temp as $$
 select private.active_budget_actor(p_game) and (private.is_game_teacher(p_game) or exists(
  select 1 from private.formal_user_roles(p_game,auth.uid()) r
  where r ~ '^(председатель[[:space:]]+правительства|((первый[[:space:]]+)?заместитель[[:space:]]+председателя[[:space:]]+правительства)|министр([[:space:]]|$)|правительство([[:space:]]|$)|сотрудник[[:space:]]+министерства[[:space:]]+финансов)'));
$$;
create or replace function private.can_request_budget_transfer(p_game uuid) returns boolean
language sql stable security definer set search_path=public,private,pg_temp as $$
 select private.can_prepare_budget(p_game) or (private.active_budget_actor(p_game) and exists(
  select 1 from private.formal_user_roles(p_game,auth.uid()) r
  where r ~ '^(губернатор([[:space:]]|$)|глава[[:space:]]+(региона|субъекта|республики|региональной[[:space:]]+администрации)|представитель[[:space:]]+(региона|субъекта|региональной[[:space:]]+администрации))'));
$$;
revoke all on function private.active_budget_actor(uuid),private.lock_budget_actor(uuid),
 private.can_prepare_budget(uuid),private.can_request_budget_transfer(uuid) from public,anon,authenticated;


CREATE OR REPLACE FUNCTION private.validate_budget_draft(p_game uuid, d jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare b jsonb;k text;v jsonb;field text;lo numeric;hi numeric;req text;item jsonb;pid uuid;yr integer;commitment numeric;begin
 select data into b from private.budget_baseline where year=2026;
 if d is null or jsonb_typeof(d)<>'object' or length(trim(coalesce(d->>'title','')))<5 or length(d->>'title')>200 or length(coalesce(d->>'note',''))>20000 then raise exception 'Укажите название расчета от 5 до 200 символов и допустимое обоснование.';end if;
 if exists(select 1 from jsonb_object_keys(d) as keys(key_name) where keys.key_name not in ('title','note','income_changes','spending_changes','revenue_adjustments','financing','terms','transfer_ids','expense_items','base_reallocations')) then raise exception 'Неизвестное поле бюджетного расчета.';end if;
 foreach field in array array['income_changes','spending_changes','revenue_adjustments','financing','terms'] loop
  if jsonb_typeof(d->field) is distinct from 'object' then raise exception 'Бюджетный расчет содержит неверную структуру: %.',field;end if;
  lo:=case field when 'income_changes' then -80 when 'spending_changes' then -80 when 'revenue_adjustments' then -50000000 when 'financing' then -50000000 else 1 end;
  hi:=case when field in ('income_changes','spending_changes') then 200 when field='terms' then 120 else 50000000 end;
  for k,v in select * from jsonb_each(d->field) loop
   if jsonb_typeof(v)<>'number' or (v#>>'{}')::numeric::text in ('NaN','Infinity','-Infinity') or (v#>>'{}')::numeric not between lo and hi then raise exception 'Число в поле % выходит за допустимый диапазон.',field;end if;
   if field in ('income_changes','revenue_adjustments') and not exists(select 1 from jsonb_array_elements(b->'income_lines') l where l->>'key'=k) then raise exception 'Неизвестная группа доходов.';end if;
   if field='spending_changes' and not exists(select 1 from jsonb_array_elements(b->'expense_lines') l where l->>'key'=k) then raise exception 'Неизвестный раздел расходов.';end if;
   if field='financing' and round((v#>>'{}')::numeric,8)<>(v#>>'{}')::numeric then raise exception 'Источник финансирования указывается с точностью до копейки.';end if;
   if field='financing' and (not b->'financing' ? k or (k<>'other' and (v#>>'{}')::numeric<0)) then raise exception 'Источник финансирования должен быть известным и иметь неотрицательную сумму.';end if;
   if field='terms' and (k not in ('ofz_fixed','ofz_float','bank_credit','external') or trunc((v#>>'{}')::numeric)<>(v#>>'{}')::numeric) then raise exception 'Срок кредита должен быть целым числом месяцев от 1 до 120.';end if;
  end loop;
 end loop;
 if (select count(*) from jsonb_object_keys(d->'financing'))<>7 then raise exception 'Укажите все семь источников финансирования, включая нулевые суммы.';end if;
 if jsonb_typeof(d->'transfer_ids') is distinct from 'array' or jsonb_array_length(d->'transfer_ids')>100 then raise exception 'Неверный список региональных запросов.';end if;
 if (select count(distinct value) from jsonb_array_elements_text(d->'transfer_ids'))<>jsonb_array_length(d->'transfer_ids') then raise exception 'Региональный запрос включен дважды.';end if;
 for req in select jsonb_array_elements_text(d->'transfer_ids') loop
  if not exists(select 1 from budget_transfer_requests where id::text=req and game_id=p_game and status<>'rejected') then raise exception 'Запрос не относится к этой игре или уже отклонен.';end if;
 end loop;

 if d ? 'base_reallocations' then
  if jsonb_typeof(d->'base_reallocations') is distinct from 'object' then raise exception 'Перераспределения базовых расходов задаются таблицей разделов.';end if;
  for k,v in select key,value from jsonb_each(d->'base_reallocations') loop
   if k='13' or not exists(select 1 from jsonb_array_elements(b->'expense_lines') l where l->>'key'=k)
    or jsonb_typeof(v) is distinct from 'number' or (v#>>'{}')::numeric::text in ('NaN','Infinity','-Infinity')
    or (v#>>'{}')::numeric not between -1000000 and 1000000 or round((v#>>'{}')::numeric,8)<>(v#>>'{}')::numeric then raise exception 'Перераспределение допускает известные профильные разделы, конечную сумму до 1 000 млрд ₽ и точность до копейки.';end if;
  end loop;
  if coalesce((select sum((value#>>'{}')::numeric) from jsonb_each(d->'base_reallocations')),0)<>0 then raise exception 'Поправка перераспределяет расходы: общая сумма бюджета не меняется.';end if;
 end if;
 if d ? 'expense_items' then
  if jsonb_typeof(d->'expense_items') is distinct from 'array' or jsonb_array_length(d->'expense_items')>100 then raise exception 'Неверная таблица расходов: не более 100 строк.';end if;
  if exists(select 1 from jsonb_array_elements(d->'expense_items') i where jsonb_typeof(i)<>'object') then raise exception 'Строка расхода должна содержать название, показатель, обоснование и сумму.';end if;
  if (select count(distinct i->>'id') from jsonb_array_elements(d->'expense_items') i)<>jsonb_array_length(d->'expense_items') then raise exception 'Каждая строка расхода должна иметь уникальный идентификатор.';end if;
  if exists(select 1 from jsonb_array_elements(d->'expense_items') i where nullif(i->>'program_id','') is not null group by lower(i->>'program_id') having count(*)>1) then raise exception 'Годовое финансирование одной госпрограммы включено дважды.';end if;
  for item in select jsonb_array_elements(d->'expense_items') loop
   if exists(select 1 from jsonb_object_keys(item) k(key_name) where key_name not in ('id','section_key','title','indicator','justification','amount','program_id','budget_year')) then raise exception 'Неизвестное поле строки расхода.';end if;
   if coalesce(item->>'id','') !~ '^[A-Za-z0-9_-]{1,80}$'
    or jsonb_typeof(item->'title') is distinct from 'string' or length(trim(item->>'title')) not between 3 and 200
    or jsonb_typeof(item->'indicator') is distinct from 'string' or length(trim(item->>'indicator')) not between 3 and 500
    or jsonb_typeof(item->'justification') is distinct from 'string' or length(trim(item->>'justification')) not between 10 and 4000 then raise exception 'Укажите название, измеримый показатель и обоснование каждой строки расхода.';end if;
   if item->>'section_key'='13' or not exists(select 1 from jsonb_array_elements(b->'expense_lines') l where l->>'key'=item->>'section_key') then raise exception 'Выберите профильный раздел расходов. Обслуживание долга рассчитывается отдельно.';end if;
   if jsonb_typeof(item->'amount') is distinct from 'number' or (item->>'amount')::numeric::text in ('NaN','Infinity','-Infinity') or (item->>'amount')::numeric not between 0.00000001 and 1000000 or round((item->>'amount')::numeric,8)<>(item->>'amount')::numeric then raise exception 'Сумма расхода должна быть положительной, до 1 000 млрд ₽ и с точностью до копейки.';end if;
   if item ? 'budget_year' and (jsonb_typeof(item->'budget_year') is distinct from 'number' or (item->>'budget_year')::numeric<>2026) then raise exception 'В федеральный бюджет 2026 года включаются расходы только 2026 года.';end if;
   if item ? 'program_id' and jsonb_typeof(item->'program_id') not in ('string','null') then raise exception 'Неверная ссылка на государственную программу.';end if;
   if nullif(item->>'program_id','') is not null then
    if item->>'program_id' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'Неверная ссылка на государственную программу.';end if;
    pid:=(item->>'program_id')::uuid;yr:=coalesce((item->>'budget_year')::numeric::integer,2026);
    select c.amount/1000000 into commitment from state_program_budget_commitments c
     join state_programs p on p.id=c.program_id and p.game_id=c.game_id
     where c.program_id=pid and c.game_id=p_game and c.budget_year=yr and c.status='approved'
      and p.status='adopted' and p.signed_at is not null and p.signed_by=c.signed_by;
    if commitment is null or commitment<=0 then raise exception 'Включить можно только подписанную и принятую госпрограмму этой игры с утверждённым финансированием 2026 года.';end if;
    if (item->>'amount')::numeric<>commitment then raise exception 'Сумма госпрограммы должна совпадать с подписанным годовым финансированием 2026 года.';end if;
   end if;
  end loop;
 end if;
end$function$;

create function private.budget_income_details(p_game uuid,d jsonb,groups jsonb,p_activity numeric,p_oil numeric) returns jsonb
language plpgsql security definer set search_path=public,private,pg_temp as $$
declare model jsonb:='[{"key":"oil_ndpi","group_key":"oil_gas","label":"Налоги на добычу нефти и газа","share":0.8,"reference_rate":40,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Расчётная стоимость добычи","driver_note":"Цена нефти и курс рубля"},{"key":"oil_extra","group_key":"oil_gas","label":"Дополнительные нефтегазовые поступления","share":0.2,"reference_rate":25,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Расчётный доход нефтегазового сектора","driver_note":"Цена нефти и курс рубля"},{"key":"vat","group_key":"turnover","label":"НДС","share":0.72,"reference_rate":22,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":false,"base_label":"Облагаемый оборот без НДС","driver_note":"Предприятия, занятость, спрос и решения в игре"},{"key":"excise","group_key":"turnover","label":"Акцизы","share":0.18,"reference_rate":20,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Расчётная стоимость подакцизных товаров","driver_note":"Деловая активность и объём потребления"},{"key":"customs","group_key":"turnover","label":"Таможенные пошлины","share":0.1,"reference_rate":10,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Расчётная стоимость облагаемого импорта","driver_note":"Деловая активность и внешняя торговля"},{"key":"profit","group_key":"income","label":"Налог на прибыль · федеральная часть","share":0.8,"reference_rate":25,"rate_unit":"percent","base_unit":"million_rubles","federal_share":0.32,"model_rate":false,"base_label":"Облагаемая прибыль организаций","driver_note":"Предприятия, активность и принятые налоговые решения"},{"key":"personal_income","group_key":"income","label":"Федеральные поступления налога на доходы физических лиц","share":0.2,"reference_rate":15,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Расчётная база федеральных поступлений","driver_note":"Деловая активность; ставка усреднена для игры"},{"key":"dividends","group_key":"assets","label":"Дивиденды по государственной доле","share":0.6,"reference_rate":100,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Прогноз выплат по государственной доле","driver_note":"Прогноз распределяемых выплат"},{"key":"asset_interest","group_key":"assets","label":"Доходы от размещения средств и использования имущества","share":0.4,"reference_rate":100,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Прогноз процентных, арендных и иных платежей","driver_note":"Утверждённый прогноз неналоговых поступлений"},{"key":"rent","group_key":"rent","label":"Платежи за другие природные ресурсы","share":1,"reference_rate":8,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Расчётная стоимость использования ресурсов","driver_note":"Объём производства и деловая активность"},{"key":"recycling","group_key":"recycling","label":"Утилизационный сбор","share":1,"reference_rate":200000,"rate_unit":"rubles","base_unit":"units","federal_share":1,"model_rate":true,"base_label":"Количество объектов, с которых взимается сбор","driver_note":"Производство и ввоз; рублёвая ставка усреднена для игры"},{"key":"other","group_key":"other","label":"Прочие налоговые и неналоговые доходы","share":1,"reference_rate":100,"rate_unit":"percent","base_unit":"million_rubles","federal_share":1,"model_rate":true,"base_label":"Прогноз остальных поступлений","driver_note":"Подтверждённые изменения прогнозных поступлений"}]'::jsonb;
 b jsonb;l jsonb;m jsonb;rate numeric;divisor numeric;driver numeric;raw_group numeric;group_tax numeric;scale numeric;tax_base numeric;amount numeric;vat numeric;profit numeric;rows jsonb:='[]';
begin
 select data into b from private.budget_baseline where year=2026;
 vat:=coalesce((select rate from game_fiscal_rates where game_id=p_game and region_code='00' and tax_key='vat'),22);
 profit:=coalesce((select rate from game_fiscal_rates where game_id=p_game and region_code='00' and tax_key='profit'),25);
 for m in select jsonb_array_elements(model) loop
  select value into l from jsonb_array_elements(b->'income_lines') where value->>'key'=m->>'group_key';
  driver:=case l->>'driver' when 'oil' then p_oil when 'activity' then p_activity else 1 end*(1+coalesce((d->'income_changes'->>(l->>'key'))::numeric,0)/100);
  group_tax:=case l->>'key' when 'turnover' then 1+.72*(vat/22-1) when 'income' then 1+.8*(profit/25-1) else 1 end;
  raw_group:=(l->>'amount')::numeric*driver*group_tax;
  select case when raw_group>0 then (value->>'amount')::numeric/raw_group else 0 end into scale from jsonb_array_elements(groups) where value->>'key'=l->>'key';
  rate:=case m->>'key' when 'vat' then vat when 'profit' then profit else (m->>'reference_rate')::numeric end;
  divisor:=case m->>'rate_unit' when 'rubles' then (m->>'reference_rate')::numeric/1000000 else (m->>'reference_rate')::numeric/100 end;
  tax_base:=(l->>'amount')::numeric*(m->>'share')::numeric/(divisor*(m->>'federal_share')::numeric)*driver*scale;
  amount:=tax_base*case m->>'rate_unit' when 'rubles' then rate/1000000 else rate/100 end*(m->>'federal_share')::numeric;
  rows:=rows||jsonb_build_array(m||jsonb_build_object('rate',rate,'base',tax_base,'collection',1,'amount',amount,'baseline',(l->>'amount')::numeric*(m->>'share')::numeric));
 end loop;
 return rows;
end;$$;
revoke all on function private.budget_income_details(uuid,jsonb,jsonb,numeric,numeric) from public,anon,authenticated;


create function private.server_budget_program_expenses(p_game uuid,items jsonb) returns jsonb
language sql stable security definer set search_path=public,private,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('program_id',p.id,'title',p.title,
  'indicators',coalesce((select string_agg(g.indicator_name||case when nullif(g.unit,'') is not null then ' ('||g.unit||')' else '' end,'; ' order by g.created_at,g.id) from state_program_goals g where g.program_id=p.id and g.game_id=p_game),''),
  'expense_breakdown',coalesce((select jsonb_agg(jsonb_build_object('indicator_name',e.indicator_name,'justification',e.justification,'amount',e.amount::text,'budget_year',e.budget_year,'component_title',c.title) order by e.position,e.id)
   from state_program_expenses e join state_program_components c on c.id=e.component_id and c.program_id=e.program_id and c.game_id=e.game_id where e.program_id=p.id and e.game_id=p_game and e.budget_year=2026),'[]'::jsonb)) order by p.title,p.id),'[]'::jsonb)
 from state_programs p where p.game_id=p_game and exists(select 1 from jsonb_array_elements(items) i where lower(i->>'program_id')=p.id::text);
$$;
revoke all on function private.server_budget_program_expenses(uuid,jsonb) from public,anon,authenticated;

create or replace function public.get_signed_state_program_budget(p_game_id uuid) returns jsonb
language plpgsql stable security definer set search_path=public,private,pg_temp as $$
begin
 if auth.uid() is null or not private.is_game_member(p_game_id) then raise exception 'Нет доступа к бюджету этой игры';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'ministry',p.responsible_ministry,'total_budget',p.total_budget::text,'program_status',p.status,'signed_by',p.signed_by,'signed_at',p.signed_at,'publication_post_id',p.publication_post_id,
  'indicators',coalesce((select string_agg(g.indicator_name||case when nullif(g.unit,'') is not null then ' ('||g.unit||')' else '' end,'; ' order by g.created_at,g.id) from state_program_goals g where g.program_id=p.id and g.game_id=p.game_id),''),
  'expense_breakdown',coalesce((select jsonb_agg(jsonb_build_object('indicator_name',e.indicator_name,'justification',e.justification,'amount',e.amount::text,'budget_year',e.budget_year,'component_title',c.title) order by e.position,e.id)
   from state_program_expenses e join state_program_components c on c.id=e.component_id and c.program_id=e.program_id and c.game_id=e.game_id where e.program_id=p.id and e.game_id=p.game_id and e.budget_year=2026),'[]'::jsonb),
  'years',(select jsonb_agg(jsonb_build_object('year',c.budget_year,'amount',c.amount::text,'status',c.status) order by c.budget_year) from state_program_budget_commitments c where c.program_id=p.id and c.game_id=p.game_id)) order by p.signed_at desc)
 from state_programs p where p.game_id=p_game_id and p.signed_at is not null),'[]'::jsonb);
end;$$;
revoke all on function public.get_signed_state_program_budget(uuid) from public,anon;
grant execute on function public.get_signed_state_program_budget(uuid) to authenticated;


CREATE OR REPLACE FUNCTION private.calculate_budget_simulator(p_game uuid, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare b jsonb;s budget_simulator_state%rowtype;p game_fiscal_policy%rowtype;a jsonb;e numeric;t numeric;fx numeric;activity numeric;cost numeric;oil numeric;firms numeric;vat numeric;profit numeric;
 il jsonb:='[]';el jsonb:='[]';l jsonb;k text;n numeric;driver numeric;tax numeric;rev numeric;exp numeric;annual numeric:=0;interest numeric;transfer_exp numeric;credit numeric;fin numeric:=0;intr numeric:=0;extr numeric;balance numeric;need numeric;uncertainty numeric;issued numeric;locked_rate numeric;quote numeric;item_amount numeric;base_amount numeric;transfer_amount numeric;interest_amount numeric;reallocation numeric;tr jsonb;
begin
 if exists(select 1 from games where id=p_game and status not in ('finished','archived')) then perform private.ensure_budget_simulator(p_game);end if;perform private.validate_budget_draft(p_game,d);
 select data into b from private.budget_baseline where year=2026;select * into s from budget_simulator_state where game_id=p_game;select * into p from game_fiscal_policy where game_id=p_game;a:=s.anchor;
 e:=coalesce((select value from state_metrics where game_id=p_game and metric_key='economy'),(a->>'economy')::numeric)-(a->>'economy')::numeric;
 t:=coalesce((select value from state_metrics where game_id=p_game and metric_key='public_trust'),(a->>'trust')::numeric)-(a->>'trust')::numeric;
 fx:=p.fx_rate*greatest(.75,least(1.3,1-e*.001-t*.001-(p.key_rate-(a->>'key_rate')::numeric)*.0015));
 select coalesce(sum(enterprises*activity_multiplier),0)/greatest(1,(a->>'enterprises')::numeric) into firms from game_fiscal_regions where game_id=p_game;
 activity:=greatest(.2,least(2,firms*(1-(p.key_rate-(a->>'key_rate')::numeric)*.007+e*.002+t*.001)));
 cost:=greatest(.7,least(1.6,1+(p.inflation-(a->>'inflation')::numeric)*.004+(fx/(a->>'fx_rate')::numeric-1)*.02));
 oil:=greatest(.1,least(3,p.oil_price/(a->>'oil_price')::numeric*fx/(a->>'fx_rate')::numeric));
 vat:=coalesce((select rate from game_fiscal_rates where game_id=p_game and region_code='00' and tax_key='vat'),22);
 profit:=coalesce((select rate from game_fiscal_rates where game_id=p_game and region_code='00' and tax_key='profit'),25);
 rev:=(b->>'income_rounding')::numeric+s.revenue_adjustment;
 for l in select jsonb_array_elements(b->'income_lines') loop
  k:=l->>'key';driver:=case l->>'driver' when 'oil' then oil when 'activity' then activity else 1 end;
  tax:=case k when 'turnover' then 1+.72*(vat/22-1) when 'income' then 1+.8*(profit/25-1) else 1 end;
  n:=round(greatest(0,(l->>'amount')::numeric*driver*tax*(1+coalesce((d->'income_changes'->>k)::numeric,0)/100)+coalesce((d->'revenue_adjustments'->>k)::numeric,0)),2);
  il:=il||jsonb_build_array(jsonb_build_object('key',k,'label',l->>'label','baseline',(l->>'amount')::numeric,'amount',n));rev:=rev+n;
 end loop;
 for k in select jsonb_object_keys(b->'financing') loop
  n:=(d->'financing'->>k)::numeric;fin:=fin+n;
  if k in ('ofz_fixed','ofz_float','bank_credit','external') then
   issued:=case when s.last_plan_id is null then 0 else least(n,(s.last_financing->>k)::numeric) end;quote:=private.budget_financing_rate(k,p.key_rate);
   locked_rate:=coalesce((s.financing_rates->>k)::numeric,private.budget_financing_rate(k,(a->>'key_rate')::numeric));
   annual:=annual+case when k='ofz_float' then n*quote/100 else (issued*locked_rate+(n-issued)*quote)/100 end;
  end if;
  if k in ('ofz_fixed','ofz_float','bank_credit') then intr:=intr+n-(s.last_financing->>k)::numeric;end if;
 end loop;
 interest:=(annual-(b->'financing'->>'ofz_fixed')::numeric*(a->>'key_rate')::numeric/100)*.5+s.service_adjustment;
 select coalesce(sum(amount) filter(where kind<>'budget_credit'),0),coalesce(sum(amount) filter(where kind='budget_credit'),0) into transfer_exp,credit from budget_transfer_requests where game_id=p_game and status<>'rejected' and d->'transfer_ids' ? id::text;
 exp:=(b->>'expense_rounding')::numeric;
 for l in select jsonb_array_elements(b->'expense_lines') loop
  k:=l->>'key';select coalesce(sum(amount),0) into transfer_amount from budget_transfer_requests where game_id=p_game and status<>'rejected' and kind<>'budget_credit' and section_key=k and d->'transfer_ids' ? id::text;
  select coalesce(sum((i->>'amount')::numeric),0) into item_amount from jsonb_array_elements(coalesce(d->'expense_items','[]'::jsonb)) i where i->>'section_key'=k;
  base_amount:=(l->>'amount')::numeric*(1+coalesce((d->'spending_changes'->>k)::numeric,0)/100)*cost;
  interest_amount:=case when k='13' then interest else 0 end;
  reallocation:=coalesce((d->'base_reallocations'->>k)::numeric,0);
  if round(greatest(0,base_amount+interest_amount),2)+reallocation<0 then raise exception 'Поправка не может уменьшить базовое ассигнование раздела ниже нуля или расходовать защищённые программы и трансферты.';end if;
  n:=round(round(greatest(0,base_amount+interest_amount),2)+reallocation+transfer_amount+item_amount,8);
  el:=el||jsonb_build_array(jsonb_build_object('key',k,'label',l->>'label','baseline',(l->>'amount')::numeric,'base_amount',round(greatest(0,base_amount+interest_amount),2)-interest_amount+reallocation,'base_reallocation_amount',reallocation,'transfer_amount',transfer_amount,'items_amount',item_amount,'interest_amount',interest_amount,'amount',n));exp:=exp+n;
 end loop;
 intr:=round(greatest(0,s.internal_debt+intr),8);extr:=round(greatest(0,s.external_debt*fx/(a->>'fx_rate')::numeric+(d->'financing'->>'external')::numeric-(s.last_financing->>'external')::numeric),8);
 rev:=round(rev,2);exp:=round(exp,8);balance:=round(rev-exp,8);need:=round(greatest(0,-balance)+credit,8);
 uncertainty:=greatest(.025,least(.2,.04+abs(e)*.001+abs(t)*.001+abs(p.inflation-(a->>'inflation')::numeric)*.003));
 select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at,r.id),'[]'::jsonb) into tr from (select r.*,f.name region_name,c.title event_title from budget_transfer_requests r join fiscal_region_reference f on f.code=r.region_code left join event_cases c on c.id=r.event_case_id and c.game_id=r.game_id where r.game_id=p_game and r.status<>'rejected' and d->'transfer_ids' ? r.id::text) r;
 return jsonb_build_object('income_lines',il,'income_details',private.budget_income_details(p_game,d,il,activity,oil),'expense_lines',el,'expense_items',coalesce(d->'expense_items','[]'::jsonb),'program_expenses',private.server_budget_program_expenses(p_game,coalesce(d->'expense_items','[]'::jsonb)),'transfer_requests',tr,'income_rounding',(b->>'income_rounding')::numeric,'revenue_adjustment',s.revenue_adjustment,'revenue',rev,'expenditure',exp,'balance',balance,'deficit',greatest(0,-balance),'surplus',greatest(0,balance),
 'deficit_pct_gdp',greatest(0,-balance)/(b->>'gdp')::numeric*100,'financing',round(fin,8),'funding_need',need,'funding_gap',round(greatest(0,need-fin),8),'cash_excess',round(greatest(0,fin-need)+greatest(0,balance),8),
 'internal_debt',intr,'external_debt',extr,'debt_total',intr+extr,'debt_pct_gdp',(intr+extr)/(b->>'gdp')::numeric*100,'annual_interest',annual,'interest_delta',interest,'transfer_expense',transfer_exp,'credit_outflow',credit,
 'reserve_remaining',round(s.reserve_remaining-(d->'financing'->>'reserves')::numeric+case when s.last_plan_id is not null then (s.last_financing->>'reserves')::numeric else 0 end,8),
 'activity',activity,'cost',cost,'fx',fx,'uncertainty',uncertainty,'revenue_low',rev*(1-uncertainty),'revenue_high',rev*(1+uncertainty),'expenditure_low',exp*(1-uncertainty),'expenditure_high',exp*(1+uncertainty));
end$function$;

CREATE OR REPLACE FUNCTION public.save_budget_simulator(p_game_id uuid, p_plan_id uuid, p_draft jsonb, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare pl budget_simulator_plans%rowtype;c jsonb;sc uuid;pol game_fiscal_policy%rowtype;st budget_simulator_state%rowtype;begin
 if not private.can_prepare_budget(p_game_id) then raise exception 'Сохранение общего проекта доступно преподавателю и бюджетной команде исполнительной власти.';end if;
 perform private.lock_budget_actor(p_game_id);
 perform pg_advisory_xact_lock(hashtextextended('budget:'||p_game_id::text,0));
 c:=private.calculate_budget_simulator(p_game_id,p_draft);select * into pol from game_fiscal_policy where game_id=p_game_id;select * into st from budget_simulator_state where game_id=p_game_id;
 if p_plan_id is not null then
  select * into pl from budget_simulator_plans where id=p_plan_id and game_id=p_game_id for update;
  if pl.id is null or pl.status<>'draft' then raise exception 'Этот расчет уже связан с документом. Создайте новый расчет для поправок.';end if;
  if p_revision is distinct from pl.revision then raise exception 'Расчет изменен другим участником. Откройте его последнюю версию перед сохранением.';end if;
  sc:=pl.scenario_id;
 else
  insert into budget_scenarios(game_id,title,budget_year,source_note,gdp,created_by,updated_by) values(p_game_id,p_draft->>'title',2026,'Млн рублей. Минфин России, первоначальный план 2026; расчет по игровым допущениям. minfin-approved-2026-v1',235067000,auth.uid(),auth.uid()) returning id into sc;
  insert into budget_simulator_plans(game_id,title,draft,calculation,scenario_id,created_by,updated_by) values(p_game_id,p_draft->>'title',p_draft,c,sc,auth.uid(),auth.uid()) returning * into pl;
 end if;
 update budget_scenarios set title=p_draft->>'title',oil_price=pol.oil_price,key_rate=pol.key_rate,revenue=(c->>'revenue')::numeric,expenditure=(c->>'expenditure')::numeric,
 debt_start=st.internal_debt+st.external_debt,financing=(c->>'financing')::numeric,balance=(c->>'balance')::numeric,deficit_pct_gdp=(c->>'deficit_pct_gdp')::numeric,debt_end=(c->>'debt_total')::numeric,debt_pct_gdp=(c->>'debt_pct_gdp')::numeric,updated_by=auth.uid(),updated_at=now() where id=sc;
 if p_plan_id is not null then update budget_simulator_plans set title=p_draft->>'title',draft=p_draft,calculation=c,revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=pl.id returning * into pl;end if;
 return jsonb_build_object('id',pl.id,'revision',pl.revision);
end$function$;

CREATE OR REPLACE FUNCTION public.create_budget_transfer_request(p_game_id uuid, p_region text, p_kind text, p_amount numeric, p_cofinancing numeric, p_purpose text, p_section text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare id uuid;b jsonb;begin
 if not private.can_request_budget_transfer(p_game_id) then raise exception 'Региональный запрос направляет представитель исполнительной власти или преподаватель.';end if;
 perform private.lock_budget_actor(p_game_id);
 if p_kind is null or p_kind not in ('grant','subsidy','subvention','budget_credit') or p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount not between 0.00000001 and 1000000 or round(p_amount,8)<>p_amount
 or p_cofinancing is null or p_cofinancing::text in ('NaN','Infinity','-Infinity') or p_cofinancing<0 or p_cofinancing>1000000 or round(p_cofinancing,8)<>p_cofinancing or (p_kind<>'subsidy' and p_cofinancing<>0) or (p_kind='subsidy' and p_cofinancing=0) then raise exception 'Укажите положительную сумму до 1 000 млрд ₽. Для субсидии необходимо положительное софинансирование.';end if;
 if p_purpose is null or length(trim(p_purpose))<30 or length(p_purpose)>10000 then raise exception 'Опишите цель, правовое основание и измеримый результат запроса: от 30 до 10 000 символов.';end if;
 if not exists(select 1 from fiscal_region_reference where code=p_region) then raise exception 'Выберите регион из карты.';end if;
 select data into b from private.budget_baseline where year=2026;
 if p_section is null or not exists(select 1 from jsonb_array_elements(b->'expense_lines') l where l->>'key'=p_section) or (p_kind='grant' and p_section<>'14') or (p_kind in ('subsidy','subvention') and p_section in ('13','14')) then raise exception 'Дотация относится к разделу 14. Субсидию и субвенцию отнесите к профильной отрасли.';end if;
 perform private.ensure_budget_simulator(p_game_id);
 insert into budget_transfer_requests(game_id,region_code,kind,amount,cofinancing,purpose,section_key,created_by) values(p_game_id,p_region,p_kind,round(p_amount,8),round(p_cofinancing,8),trim(p_purpose),p_section,auth.uid()) returning budget_transfer_requests.id into id;
 insert into budget_simulator_ledger(game_id,kind,note,amount,source_key) values(p_game_id,'request','Поступил региональный запрос: '||(select name from fiscal_region_reference where code=p_region)||' · '||trim(p_purpose),p_amount,'request:'||id);
 return id;
end$function$;

create function public.create_budget_event_transfer_request(
 p_game_id uuid,p_event_case_id uuid,p_region text,p_kind text,p_amount numeric,p_cofinancing numeric,
 p_purpose text,p_section text,p_expected_result text
) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$
declare c event_cases%rowtype;rid uuid;b jsonb;
begin
 if not private.can_request_budget_transfer(p_game_id) then raise exception 'Запрос направляет действующий представитель Правительства, региона или преподаватель.';end if;
 perform private.lock_budget_actor(p_game_id);
 perform pg_advisory_xact_lock(hashtextextended('budget:'||p_game_id::text,0));
 select * into c from event_cases where id=p_event_case_id and game_id=p_game_id for share;
 if c.id is null or c.status<>'ready' or jsonb_typeof(c.comic_scene->'budget_request') is distinct from 'object'
  or c.comic_scene->>'region_code' is distinct from p_region then raise exception 'Выберите бюджетное событие этого региона в текущей игре.';end if;
 if not exists(select 1 from event_assignments where case_id=c.id and game_id=p_game_id) then raise exception 'Сначала начните региональное событие. Запрос нельзя основывать на ещё не начавшемся сценарии.';end if;
 if not private.can_prepare_budget(p_game_id) and not exists(select 1 from event_assignments where case_id=c.id and game_id=p_game_id and recipient_id=auth.uid()) then raise exception 'Региональный представитель направляет запрос только по событию, назначенному ему.';end if;
 if p_expected_result is null or length(trim(p_expected_result)) not between 10 and 4000 then raise exception 'Укажите измеримый ожидаемый результат запроса: от 10 до 4 000 символов.';end if;
 if exists(select 1 from budget_transfer_requests where game_id=p_game_id and event_case_id=c.id and region_code=p_region) then raise exception 'По этому региональному событию запрос уже направлен.';end if;
 if p_kind is null or p_kind not in ('grant','subsidy','subvention','budget_credit')
  or p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount not between 0.00000001 and 1000000 or round(p_amount,8)<>p_amount
  or p_cofinancing is null or p_cofinancing::text in ('NaN','Infinity','-Infinity') or p_cofinancing<0 or p_cofinancing>1000000 or round(p_cofinancing,8)<>p_cofinancing
  or (p_kind<>'subsidy' and p_cofinancing<>0) or (p_kind='subsidy' and p_cofinancing=0) then raise exception 'Укажите положительную сумму до 1 000 млрд ₽ с точностью до копейки. Для субсидии необходимо софинансирование.';end if;
 if p_purpose is null or length(trim(p_purpose)) not between 30 and 10000 then raise exception 'Обоснуйте цель, смету и основание запроса: от 30 до 10 000 символов.';end if;
 if not exists(select 1 from fiscal_region_reference where code=p_region) then raise exception 'Выберите регион из карты.';end if;
 select data into b from private.budget_baseline where year=2026;
 if p_section is null or p_section='13' or not exists(select 1 from jsonb_array_elements(b->'expense_lines') l where l->>'key'=p_section)
  or (p_kind='grant' and p_section<>'14') or (p_kind in ('subsidy','subvention') and p_section='14') then raise exception 'Дотация относится к разделу 14; целевая помощь — к профильной отрасли. Обслуживание долга рассчитывается отдельно.';end if;
 perform private.ensure_budget_simulator(p_game_id);
 insert into budget_transfer_requests(game_id,region_code,kind,amount,cofinancing,purpose,section_key,created_by,event_case_id,expected_result)
  values(p_game_id,p_region,p_kind,round(p_amount,8),round(p_cofinancing,8),trim(p_purpose),p_section,auth.uid(),c.id,trim(p_expected_result)) returning id into rid;
 insert into budget_simulator_ledger(game_id,kind,note,amount,source_key)
  values(p_game_id,'request','Региональное событие «'||c.title||'»: '||(select name from fiscal_region_reference where code=p_region)||'. '||trim(p_purpose),p_amount,'request:'||rid);
 return rid;
end;$$;
revoke all on function public.create_budget_event_transfer_request(uuid,uuid,text,text,numeric,numeric,text,text,text) from public,anon;
grant execute on function public.create_budget_event_transfer_request(uuid,uuid,text,text,numeric,numeric,text,text,text) to authenticated;


CREATE OR REPLACE FUNCTION public.start_regional_case(p_case_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare c event_cases%rowtype;initial_game uuid;
begin
 select * into c from event_cases where id=p_case_id;initial_game:=c.game_id;
 if c.id is null or not (c.comic_scene ? 'region_code') or c.status<>'ready' then raise exception 'Региональная задача недоступна.';end if;
 if c.comic_scene ? 'budget_request' then
  if not private.can_request_budget_transfer(c.game_id) then raise exception 'Бюджетное событие начинает действующий представитель Правительства, региона или преподаватель.';end if;
  perform private.lock_budget_actor(c.game_id);
  select * into c from event_cases where id=p_case_id and game_id=initial_game for update;
  if c.id is null or c.status<>'ready' or not(c.comic_scene ? 'budget_request') then raise exception 'Региональное бюджетное событие изменено. Обновите список.';end if;
 else
  select * into c from event_cases where id=p_case_id and game_id=initial_game for update;
  if c.id is null or c.status<>'ready' then raise exception 'Региональная задача недоступна.';end if;
  if not exists(select 1 from game_members where game_id=c.game_id and user_id=auth.uid() and kind='student') then raise exception 'Задачу начинает студент текущей игры.';end if;
 end if;
 if exists(select 1 from event_assignments where case_id=c.id and recipient_id=auth.uid()) then return c.id;end if;
 if exists(select 1 from event_case_outcomes where case_id=c.id) then raise exception 'Этот кейс уже завершён. Итог доступен участникам его решения.';end if;
 if exists(select 1 from event_decisions where case_id=c.id) then raise exception 'Голосование уже началось. Новых участников приглашают до первого голоса.';end if;
 insert into event_assignments(case_id,game_id,recipient_id,created_by) values(c.id,c.game_id,auth.uid(),auth.uid()) on conflict do nothing;
 return c.id;
end$function$;

CREATE OR REPLACE FUNCTION public.create_budget_simulator_document(p_plan_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare pl budget_simulator_plans%rowtype;c jsonb;body text;l jsonb;pe jsonb;req record;doc uuid;begin
 select * into pl from budget_simulator_plans where id=p_plan_id;
 if pl.id is null or not private.can_prepare_budget(pl.game_id) then raise exception 'Нет права формировать проект бюджета этой игры.';end if;
 perform private.lock_budget_actor(pl.game_id);
 perform pg_advisory_xact_lock(hashtextextended('budget:'||pl.game_id::text,0));select * into pl from budget_simulator_plans where id=p_plan_id for update;
 if pl.document_id is not null then return pl.document_id;end if;
 c:=private.calculate_budget_simulator(pl.game_id,pl.draft);
 if (c->>'funding_gap')::numeric>0 or (c->>'reserve_remaining')::numeric<0 then raise exception 'Покройте дефицит и выдачу бюджетных кредитов допустимыми источниками. Нельзя использовать резерв сверх остатка.';end if;
 if length(trim(coalesce(pl.draft->>'note','')))<30 then raise exception 'Добавьте пояснительную записку с основанием решений: не менее 30 символов.';end if;
 body:=E'РОССИЙСКАЯ ФЕДЕРАЦИЯ\nПРОЕКТ ФЕДЕРАЛЬНОГО ЗАКОНА\nО федеральном бюджете на 2026 год\n\nСтатья 1. Основные характеристики федерального бюджета\n'||
 'Утвердить доходы '||(c->>'revenue')||' млн рублей, расходы '||(c->>'expenditure')||' млн рублей, '||case when (c->>'balance')::numeric<0 then 'дефицит '||(c->>'deficit') else 'профицит '||(c->>'surplus') end||E' млн рублей.\n'||
 'Расчетный государственный внутренний долг на конец года: '||(c->>'internal_debt')||' млн рублей. Внешний долг в рублевом эквиваленте: '||(c->>'external_debt')||E' млн рублей.\n\nСтатья 2. Распределение доходов\n';
 for l in select jsonb_array_elements(c->'income_lines') loop body:=body||(l->>'label')||': '||(l->>'amount')||E' млн рублей.\n';end loop;
 body:=body||'Корректировка округления: '||(c->>'income_rounding')||' млн рублей. Отдельная игровая корректировка доходов: '||(c->>'revenue_adjustment')||E' млн рублей.\n\nСтатья 3. Распределение расходов по разделам\n';
 for l in select jsonb_array_elements(c->'expense_lines') loop body:=body||(l->>'key')||'. '||(l->>'label')||': '||(l->>'amount')||E' млн рублей.\n';end loop;
 body:=body||E'Корректировка округления: −100 млн рублей.\n\nСтатья 4. Источники финансирования дефицита\n'||
 'ОФЗ с постоянным купоном: '||(pl.draft->'financing'->>'ofz_fixed')||' млн рублей; ОФЗ с переменным купоном: '||(pl.draft->'financing'->>'ofz_float')||E' млн рублей.\n'||
 'Кредиты российских кредитных организаций: '||(pl.draft->'financing'->>'bank_credit')||' млн рублей; внешние заимствования: '||(pl.draft->'financing'->>'external')||E' млн рублей.\n'||
 'Резервные средства ФНБ: '||(pl.draft->'financing'->>'reserves')||' млн рублей; приватизация акций: '||(pl.draft->'financing'->>'privatization')||' млн рублей; прочие источники: '||(pl.draft->'financing'->>'other')||E' млн рублей.\n'||
 'Всего источников: '||(c->>'financing')||' млн рублей; потребность с учетом бюджетных кредитов: '||(c->>'funding_need')||E' млн рублей.\n\nСтатья 5. Межбюджетные отношения\n';
 for req in select r.*,f.name from budget_transfer_requests r join fiscal_region_reference f on f.code=r.region_code where r.game_id=pl.game_id and pl.draft->'transfer_ids' ? r.id::text loop
  body:=body||req.name||': '||case req.kind when 'grant' then 'дотация' when 'subsidy' then 'субсидия' when 'subvention' then 'субвенция' else 'бюджетный кредит' end||' '||req.amount||' млн рублей; софинансирование '||req.cofinancing||' млн рублей. '||req.purpose||E'\n';
 end loop;
 body:=body||E'Целевые трансферты включены в профильные разделы, дотации — в раздел 14. Бюджетные кредиты являются возвратным финансированием.\n\nПОЯСНИТЕЛЬНАЯ ЗАПИСКА\n'||(pl.draft->>'note')||E'\n\nИСХОДНЫЕ ДАННЫЕ И ДОПУЩЕНИЯ\nПервоначально утвержденный план 2026 года: Минфин России, «Бюджет для граждан 2026–2028», https://ob.ulminfin.ru/images/brochure/Byudjet_federal/2026f/BDG_2026.pdf. Все суммы — млн рублей. Изменения активности, процентные условия и риски — учебная модель. Налоговые ставки изменяются отдельными НПА.\n\nПолномочия и процедура: БК РФ, статьи 103, 129–133, 192, 199–207; Конституция РФ, статьи 104–107. Подписи и дата фиксируются участниками процедуры в реестре НПА.';
 body:=body||E'\n\nПРИЛОЖЕНИЕ 1. РАСЧЁТ ДОХОДОВ ПО СТАТЬЯМ\n';
 for l in select jsonb_array_elements(c->'income_details') loop
  body:=body||(l->>'label')||': ставка '||(l->>'rate')||case l->>'rate_unit' when 'rubles' then ' рублей за единицу' else ' %' end||', база '||(l->>'base')||case l->>'base_unit' when 'units' then ' единиц' else ' млн рублей' end||', доля федерального бюджета '||((l->>'federal_share')::numeric*100)||' %; доход '||(l->>'amount')||E' млн рублей.\n';
 end loop;
 body:=body||E'Эффективные ставки и распределение внутри доходных групп учебные; НДС и налог на прибыль используют действующие ставки игры. Округление и отдельные корректировки указаны отдельно.\n\nПРИЛОЖЕНИЕ 2. ОБОСНОВАННЫЕ РАСХОДЫ\n';
 for l in select jsonb_array_elements(c->'expense_items') loop
  body:=body||'Раздел '||(l->>'section_key')||'. '||(l->>'title')||'. Показатель: '||(l->>'indicator')||'. Обоснование: '||(l->>'justification')||'. Сумма: '||((l->>'amount')::numeric*1000000)||' рублей.'||case when nullif(l->>'program_id','') is not null then ' Госпрограмма: '||(select title from state_programs where id=(l->>'program_id')::uuid and game_id=pl.game_id)||'; год 2026.' else '' end||E'\n';
 end loop;
 for pe in select jsonb_array_elements(c->'program_expenses') loop
  body:=body||E'\nПОДПИСАННАЯ ГОСПРОГРАММА: '||(pe->>'title')||E'\nПоказатели программы: '||(pe->>'indicators')||E'\n';
  for l in select jsonb_array_elements(pe->'expense_breakdown') loop
   body:=body||(l->>'component_title')||'. '||(l->>'indicator_name')||'. Основание: '||(l->>'justification')||'. 2026 год: '||(l->>'amount')||E' рублей.\n';
  end loop;
 end loop;
 body:=body||E'\nПРИЛОЖЕНИЕ 3. РЕГИОНАЛЬНЫЕ СОБЫТИЯ И ЗАПРОСЫ\n';
 for l in select jsonb_array_elements(c->'transfer_requests') loop
  body:=body||(l->>'region_name')||'. Событие: '||coalesce(l->>'event_title','Запрос предыдущей редакции')||'. Основание: '||(l->>'purpose')||'. Ожидаемый результат: '||coalesce(l->>'expected_result','Указан в обосновании запроса')||'. Федеральная сумма: '||((l->>'amount')::numeric*1000000)||' рублей. Софинансирование: '||((l->>'cofinancing')::numeric*1000000)||E' рублей.\n';
 end loop;
 body:=body||E'\n\nРасчетные приложения закреплены за этим проектом. Для изменения сумм используйте калькулятор вкладки «Бюджет» и сформируйте новую редакцию проекта. Редактирование пояснений в реестре само по себе не меняет числовые приложения.';
 for req in select a.*,v.result_yes,v.result_no,v.result_abstain from budget_faction_amendments a left join game_votes v on v.id=a.vote_id where a.plan_id=pl.id and a.status='applied' order by a.applied_revision loop
  body:=body||E'\n\nИСТОРИЯ ПОДГОТОВКИ: ПОПРАВКА '||req.party_name||E'\n'||req.title||'. Перераспределение из раздела '||req.from_section||' в раздел '||req.to_section||': '||req.amount||' млн рублей. Включена в редакцию '||req.applied_revision||E'.\n'||req.reason||E'\nПредварительное голосование: за '||coalesce(req.result_yes,0)||', против '||coalesce(req.result_no,0)||', воздержались '||coalesce(req.result_abstain,0)||' мандатов. Итоговые суммы определяются расчетными приложениями проекта.';
 end loop;
 doc:=public.create_formal_document(pl.game_id,13,pl.title,'federal_budget','government','Правительство Российской Федерации',body,null,null,null,'budget',jsonb_build_object('budget_simulator_plan_id',pl.id,'budget_scenario_id',pl.scenario_id,'budget_base_plan_id',(select last_plan_id from budget_simulator_state where game_id=pl.game_id),'budget_year',2026,'unit','million_rubles','budget_snapshot',c,'budget_draft',pl.draft,'revision',1,'educational_draft',true));
 update formal_documents set metadata=metadata||jsonb_build_object('budget_amendments',
  (select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'party_name',a.party_name,'reason',a.reason,'amount',a.amount,'from_section',a.from_section,'to_section',a.to_section,'applied_revision',a.applied_revision,'vote_id',a.vote_id,'yes',v.result_yes,'no',v.result_no,'abstain',v.result_abstain) order by a.applied_revision),'[]'::jsonb) from budget_faction_amendments a left join game_votes v on v.id=a.vote_id where a.plan_id=pl.id and a.status='applied')) where id=doc;
 update budget_simulator_plans set status='document',document_id=doc,calculation=c,updated_at=now() where id=pl.id;
 update budget_scenarios set status='final',formal_document_id=doc,updated_at=now() where id=pl.scenario_id;
 insert into budget_simulator_ledger(game_id,kind,note,amount,source_key) values(pl.game_id,'document','Сформирован проект закона; экономические изменения ожидают опубликования.',(c->>'expenditure')::numeric,'document:'||doc);
 return doc;
end$function$;

CREATE OR REPLACE FUNCTION private.apply_budget_simulator_plan(p_game uuid, p_plan_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare doc formal_documents%rowtype;pl budget_simulator_plans%rowtype;s budget_simulator_state%rowtype;c jsonb;fresh jsonb;req budget_transfer_requests%rowtype;before_row jsonb;after_row jsonb;k text;old_amount numeric;new_amount numeric;delta numeric;leftover numeric;ct budget_finance_contracts%rowtype;caseid uuid;total_internal numeric;total_external numeric;base_plan text;begin
 select d.* into doc from formal_documents d join budget_simulator_plans p on p.document_id=d.id and p.game_id=d.game_id where p.id=p_plan_id and p.game_id=p_game;
 if doc.id is null or doc.status_code<>'published' or doc.doc_type<>'federal_budget' or doc.workflow_key<>'budget' or not doc.metadata ? 'budget_simulator_plan_id' then return false;end if;
 if not exists(select 1 from games where id=doc.game_id and status not in ('finished','archived')) then raise exception 'Завершённая или архивная игра не исполняет новые бюджетные обязательства.';end if;
 if auth.uid() is not null then perform private.lock_budget_actor(doc.game_id);end if;
 perform pg_advisory_xact_lock(hashtextextended('budget:'||doc.game_id::text,0));
 select * into pl from budget_simulator_plans where id::text=doc.metadata->>'budget_simulator_plan_id' and game_id=doc.game_id and document_id=doc.id for update;
 if pl.id is null then raise exception 'Не найден расчет, связанный с этим проектом бюджета.';end if;
 if pl.status='published' then return false;end if;
 select * into s from budget_simulator_state where game_id=doc.game_id for update;
 base_plan:=doc.metadata->>'budget_base_plan_id';
 if base_plan is distinct from s.last_plan_id::text then raise exception 'После подготовки проекта опубликован другой бюджет. Создайте обновленный расчет и проект с учетом действующего бюджета.';end if;
 c:=pl.calculation;fresh:=private.calculate_budget_simulator(doc.game_id,pl.draft);
 if (c->>'funding_gap')::numeric>(case when c ? 'expense_items' then 0 else 1 end) or (fresh->>'reserve_remaining')::numeric<0 then raise exception 'Проект не обеспечен финансированием либо доступный резерв изменился. Обновите расчет.';end if;
 insert into budget_simulator_ledger(game_id,kind,note,amount,source_key) values(pl.game_id,'publication','Опубликован '||doc.registry_no||'. Применены источники финансирования и включенные региональные запросы.',(c->>'expenditure')::numeric,'published:'||pl.id) on conflict do nothing;
 if not found then return false;end if;
 -- Only newly included requests are paid. Reprinting a granted request in an amendment never pays twice.
 for req in select * from budget_transfer_requests where game_id=pl.game_id and status='requested' and pl.draft->'transfer_ids' ? id::text for update loop
  select to_jsonb(r) into before_row from game_fiscal_regions r where game_id=pl.game_id and region_code=req.region_code for update;
  update game_fiscal_regions set transfer_in=transfer_in+case when req.kind<>'budget_credit' then req.amount else 0 end,budget_credit_cash=budget_credit_cash+case when req.kind='budget_credit' then req.amount else 0 end,expenditure=expenditure+case when req.kind='subsidy' then req.amount+req.cofinancing when req.kind='subvention' then req.amount else 0 end,
   debt=debt+case when req.kind='budget_credit' then req.amount else 0 end,updated_at=now()
  where game_id=pl.game_id and region_code=req.region_code returning to_jsonb(game_fiscal_regions.*) into after_row;
  update budget_transfer_requests set status='granted',plan_id=pl.id,document_id=doc.id,decided_at=now(),maturity_month=case when req.kind='budget_credit' then s.month+12 else null end where id=req.id;
  insert into fiscal_change_ledger(game_id,region_code,source_type,source_id,note,before_values,after_values,actor_id) values(pl.game_id,req.region_code,'budget_transfer',req.id::text,'Бюджетный запрос исполнен по '||doc.registry_no||': '||req.purpose,before_row,after_row,doc.author_id) on conflict do nothing;
  insert into budget_simulator_ledger(game_id,kind,note,amount,source_key) values(pl.game_id,'transfer','Перечислено региону '||(select name from fiscal_region_reference where code=req.region_code)||'. '||req.purpose,req.amount,'transfer:'||req.id) on conflict do nothing;
 end loop;
 foreach k in array array['ofz_fixed','ofz_float','bank_credit','external'] loop
  new_amount:=(pl.draft->'financing'->>k)::numeric;
  -- Official debt at the end of 2026 already incorporates the initial net borrowing plan.
  -- The first simulated law creates its obligations without adding that same plan to debt again.
  old_amount:=case when s.last_plan_id is null then 0 else (s.last_financing->>k)::numeric end;delta:=new_amount-old_amount;
  if delta>0 then
   insert into budget_finance_contracts(game_id,plan_id,source_key,principal,annual_rate,maturity_month)
   values(pl.game_id,pl.id,k,case when k='external' then round(delta/(fresh->>'fx')::numeric*(s.anchor->>'fx_rate')::numeric,8) else delta end,private.budget_financing_rate(k,(select key_rate from game_fiscal_policy where game_id=pl.game_id)),s.month+coalesce((pl.draft->'terms'->>k)::integer,60));
  elsif delta<0 then
   leftover:=-delta;
   for ct in select * from budget_finance_contracts where game_id=pl.game_id and source_key=k and status in ('active','due') order by maturity_month,id for update loop
    delta:=least(ct.principal,leftover);update budget_finance_contracts set principal=principal-delta,status=case when principal-delta=0 then 'paid' else status end where id=ct.id;leftover:=leftover-delta;if leftover<=0 then exit;end if;
   end loop;
  end if;
  if new_amount>0 then
   select id into caseid from event_cases where game_id=pl.game_id and case_key='budget-risk-2026-'||k;
   if caseid is not null then insert into private.budget_deferred_risks(game_id,case_id,source_key,due_at,due_month) values(pl.game_id,caseid,k,now()+interval '15 minutes',s.month+1) on conflict(game_id,source_key) do nothing;end if;
  end if;
 end loop;
 foreach k in array array['reserves','privatization'] loop
  if (pl.draft->'financing'->>k)::numeric>0 then
   select id into caseid from event_cases where game_id=pl.game_id and case_key='budget-risk-2026-'||k;
   if caseid is not null then insert into private.budget_deferred_risks(game_id,case_id,source_key,due_at,due_month) values(pl.game_id,caseid,k,now()+interval '15 minutes',s.month+1) on conflict(game_id,source_key) do nothing;end if;
  end if;
 end loop;
 update budget_simulator_state set internal_debt=(fresh->>'internal_debt')::numeric,
  -- Store foreign-currency principal in anchor-FX equivalent to prevent compounding FX revaluation.
  external_debt=round((fresh->>'external_debt')::numeric/(fresh->>'fx')::numeric*(anchor->>'fx_rate')::numeric,8),
  reserve_remaining=(fresh->>'reserve_remaining')::numeric,
  financing_rates=coalesce((select jsonb_object_agg(q.source_key,q.rate) from (select source_key,sum(principal*annual_rate)/nullif(sum(principal),0) rate from budget_finance_contracts where game_id=pl.game_id and status in ('active','due') and principal>0 group by source_key)q),financing_rates),
  last_financing=pl.draft->'financing',last_plan_id=pl.id,last_document_id=doc.id,version=version+1,updated_at=now() where game_id=pl.game_id;
 update budget_simulator_plans set status='published',updated_at=now() where id=pl.id;
 insert into game_events(game_id,round_no,category,severity,title,body,created_by) values(pl.game_id,13,'Бюджет','notice','Федеральный бюджет принят и опубликован',
  doc.registry_no||'. Доходы: '||(c->>'revenue')||' млн ₽; расходы: '||(c->>'expenditure')||' млн ₽; дефицит: '||(c->>'deficit')||' млн ₽; профицит: '||(c->>'surplus')||' млн ₽. Региональные запросы и долговые обязательства отражены в общем симуляторе.',doc.author_id);
 return true;
end$function$;

CREATE OR REPLACE FUNCTION public.sign_formal_document(p_document_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare d public.formal_documents%rowtype;access jsonb;
begin
 select * into d from public.formal_documents where id=p_document_id for update;
 if d.workflow_key='budget' or d.doc_type='federal_budget' then perform private.lock_budget_actor(d.game_id);end if;
 access:=public.get_formal_document_tools(p_document_id);
 if not (access->>'can_sign')::boolean then raise exception 'Подписание этой редакции сейчас недоступно';end if;
 if d.status_code in ('signed','published','adopted') then
 insert into public.formal_document_history(document_id,game_id,actor_id,action,from_status,to_status,from_owner,to_owner,note)
 values(d.id,d.game_id,auth.uid(),'Подписана редакция '||coalesce(d.metadata->>'revision','1'),d.status_code,d.status_code,d.current_owner_key,d.current_owner_key,p_note);
 else perform public.advance_formal_document(d.id,'advance',coalesce(nullif(p_note,''),'Подписано уполномоченным лицом'));end if;
end;$function$;

CREATE OR REPLACE FUNCTION public.send_formal_document(p_document_id uuid, p_destination text, p_recipient_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_move boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare d public.formal_documents%rowtype;access jsonb;next_owner text;r record;n integer:=0;before_status text;
begin
 select * into d from public.formal_documents where id=p_document_id for update;
 if d.workflow_key='budget' or d.doc_type='federal_budget' then perform private.lock_budget_actor(d.game_id);end if;
 access:=public.get_formal_document_tools(p_document_id);
 if not (access->>'can_copy')::boolean then raise exception 'Направление документа недоступно';end if;
 if length(trim(coalesce(p_note,'')))>2000 then raise exception 'Сопроводительный текст слишком длинный';end if;
 next_owner:=access->>'next_owner';before_status:=d.status_code;
 if p_move and (not (access->>'can_manage')::boolean or p_destination is distinct from next_owner or next_owner in ('author','system') or next_owner is null) then
 raise exception 'Передача по процедуре возможна только следующему ответственному органу';end if;
 if not p_move and p_destination not in ('person','president','gd','gd_staff','gd_council','committee','sf','government','ministry','municipality','teacher') then raise exception 'Выберите адресата';end if;
 for r in select gm.user_id,gm.full_name from public.game_members gm
 where gm.game_id=d.game_id and gm.kind<>'observer'
 and (p_recipient_id is null or gm.user_id=p_recipient_id)
 and (p_destination='person' or (p_destination='teacher' and gm.kind='teacher')
 or (gm.kind='student' and exists(select 1 from private.formal_user_roles(d.game_id,gm.user_id) rt where case p_destination
 when 'president' then rt like '%президент%'
 when 'gd' then rt like '%депутат%' or rt like '%государственн%дум%'
 when 'gd_staff' then rt like '%председател%дум%'
 when 'gd_council' then (rt like '%совет%' or rt like '%председател%') and rt like '%дум%'
 when 'committee' then rt like '%комитет%' or rt like '%депутат%'
 when 'sf' then rt like '%сенатор%' or rt like '%совет федерац%'
 when 'government' then rt like '%правительств%' or rt like '%министр%'
 when 'ministry' then rt like '%министр%'
 when 'municipality' then rt like '%муницип%' or rt like '%глава города%' or rt like '%администрац%'
 else false end)))
 loop
 insert into public.formal_document_deliveries(game_id,document_id,sender_id,recipient_id,destination,note,delivery_kind)
 values(d.game_id,d.id,auth.uid(),r.user_id,p_destination,nullif(trim(p_note),''),case when p_move then 'procedure' else 'copy' end);n:=n+1;
 end loop;
 if n=0 then raise exception 'У выбранного адресата нет назначенных участников игры';end if;
 if p_move then perform public.advance_formal_document(d.id,'advance',p_note);end if;
 insert into public.formal_document_history(document_id,game_id,actor_id,action,from_status,to_status,from_owner,to_owner,note)
 select d.id,d.game_id,auth.uid(),case when p_move then 'Документ передан адресатам по процедуре' else 'Направлена копия документа' end,before_status,f.status_code,d.current_owner_key,f.current_owner_key,
 concat_ws(' · ',p_destination,'Получателей: '||n,case when p_recipient_id is not null then (select full_name from public.game_members where game_id=d.game_id and user_id=p_recipient_id) end,nullif(trim(p_note),''))
 from public.formal_documents f where f.id=d.id;
 return n;
end;$function$;

CREATE OR REPLACE FUNCTION public.repay_budget_finance_contract(p_contract_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare ct budget_finance_contracts%rowtype;s budget_simulator_state%rowtype;amount numeric;begin
 select * into ct from budget_finance_contracts where id=p_contract_id;
 if ct.id is null or not private.can_prepare_budget(ct.game_id) then raise exception 'Погашение доступно бюджетной команде этой игры.';end if;
 perform private.lock_budget_actor(ct.game_id);
 perform pg_advisory_xact_lock(hashtextextended('budget:'||ct.game_id::text,0));select * into ct from budget_finance_contracts where id=p_contract_id for update;select * into s from budget_simulator_state where game_id=ct.game_id for update;
 if ct.status='paid' then return;end if;
 amount:=case when ct.source_key='external' then ct.principal*(private.calculate_budget_simulator(ct.game_id,(select draft from budget_simulator_plans where id=s.last_plan_id))->>'fx')::numeric/(s.anchor->>'fx_rate')::numeric else ct.principal end;amount:=round(amount,8);
 if s.reserve_remaining<amount then raise exception 'Недостаточно доступного резерва. Подготовьте изменения в бюджет и источниках рефинансирования.';end if;
 insert into budget_simulator_ledger(game_id,kind,note,amount,source_key) values(ct.game_id,'principal','Погашен основной долг по '||ct.source_key||' из доступного резерва. Проценты учитываются отдельно.',amount,'repay:'||ct.id) on conflict do nothing;if not found then return;end if;
 update budget_simulator_state set reserve_remaining=round(reserve_remaining-amount,8),internal_debt=round(greatest(0,internal_debt-case when ct.source_key<>'external' then ct.principal else 0 end),8),external_debt=round(greatest(0,external_debt-case when ct.source_key='external' then ct.principal else 0 end),8),version=version+1,updated_at=now() where game_id=ct.game_id;
 update budget_finance_contracts set status='paid',principal=0 where id=ct.id;
end$function$;

CREATE OR REPLACE FUNCTION public.repay_budget_transfer(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare r budget_transfer_requests%rowtype;reg game_fiscal_regions%rowtype;before_row jsonb;after_row jsonb;begin
 select * into r from budget_transfer_requests where id=p_request_id;
 if r.id is null or not private.can_request_budget_transfer(r.game_id) then raise exception 'Нет права возвращать бюджетный кредит этой игры.';end if;
 perform private.lock_budget_actor(r.game_id);
 perform pg_advisory_xact_lock(hashtextextended('budget:'||r.game_id::text,0));select * into r from budget_transfer_requests where id=p_request_id for update;
 if r.kind<>'budget_credit' or r.status<>'granted' then raise exception 'Этот запрос не является выданным бюджетным кредитом.';end if;
 if r.repaid_at is not null then return;end if;
 select * into reg from game_fiscal_regions where game_id=r.game_id and region_code=r.region_code for update;
 if reg.budget_credit_cash<r.amount then raise exception 'В учебном остатке региона недостаточно средств для возврата кредита.';end if;
 before_row:=to_jsonb(reg);
 update game_fiscal_regions set budget_credit_cash=round(budget_credit_cash-r.amount,8),debt=round(greatest(0,debt-r.amount),8),updated_at=now() where game_id=r.game_id and region_code=r.region_code returning to_jsonb(game_fiscal_regions.*) into after_row;
 update budget_transfer_requests set repaid_at=now() where id=r.id;
 update budget_simulator_state set reserve_remaining=round(reserve_remaining+r.amount,8),version=version+1,updated_at=now() where game_id=r.game_id;
 insert into fiscal_change_ledger(game_id,region_code,source_type,source_id,note,before_values,after_values,actor_id) values(r.game_id,r.region_code,'budget_repayment',r.id::text,'Возвращен бюджетный кредит',before_row,after_row,auth.uid()) on conflict do nothing;
 insert into budget_simulator_ledger(game_id,kind,note,amount,source_key) values(r.game_id,'regional_repayment','Регион вернул бюджетный кредит. Возврат — источник финансирования, а не налоговый доход.',r.amount,'regional-repay:'||r.id) on conflict do nothing;
end$function$;

CREATE OR REPLACE FUNCTION private.fiscal_event_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare c event_cases%rowtype;fx jsonb;rc text;before_row jsonb;after_row jsonb;opt integer;
begin
 select * into c from event_cases where id=new.case_id;
 if coalesce(new.winner,'') !~ '^option_[0-9]+$' then return new;end if;
 opt:=substring(new.winner from 8)::integer-1;fx:=c.effect_plan->'options'->opt->'fiscal_effect';rc:=c.comic_scene->>'region_code';
 if fx is null or rc is null then return new;end if;
 if exists(select 1 from fiscal_change_ledger where game_id=c.game_id and source_type='event' and source_id=c.id::text and region_code=rc) then return new;end if;
 perform private.ensure_fiscal_game(c.game_id);
 select to_jsonb(r) into before_row from game_fiscal_regions r where game_id=c.game_id and region_code=rc for update;
 update game_fiscal_regions set enterprises=least(10000000,greatest(0,enterprises+coalesce((fx->>'enterprises')::int,0))),expenditure=greatest(0,expenditure+coalesce((fx->>'expenditure')::numeric,0)),transfer_in=greatest(0,transfer_in+coalesce((fx->>'transfer_in')::numeric,0)),activity_multiplier=greatest(.05,least(5,activity_multiplier+coalesce((fx->>'activity')::numeric,0))),cost_multiplier=greatest(.05,least(5,cost_multiplier+coalesce((fx->>'cost')::numeric,0))),updated_at=now() where game_id=c.game_id and region_code=rc returning to_jsonb(game_fiscal_regions.*) into after_row;
 insert into fiscal_change_ledger(game_id,region_code,source_type,source_id,note,before_values,after_values) values(c.game_id,rc,'event',c.id::text,'Исход кейса «'||c.title||'»',before_row,after_row);
 return new;
end $function$;

