ия","amount":690},{"name":"Организация переезда","amount":90},{"name":"Социальное сопровождение","amount":90}],"justification":"Реестр семей и заключения по домам обосновывают потребность. Смета отделена от ремонта сетей, чтобы расходы не удваивались; регион обеспечивает 180 млн ₽."}}}]'::jsonb;
begin
 if not exists(select 1 from games where id=p_game and status not in ('finished','archived')) then return;end if;
 insert into event_cases(game_id,case_key,title,situation,category,seriousness,audience,allowed_roles,
  decision_options,effect_plan,source_url,source_note,verified,status,comic_scene,created_by)
 select p_game,c->>'case_key',c->>'title',c->>'situation',c->>'category',c->>'seriousness',c->>'audience',
  array(select jsonb_array_elements_text(c->'allowed_roles')),c->'decision_options',c->'effect_plan',
  c->>'source_url',c->>'source_note',coalesce((c->>'verified')::boolean,false),'ready',c->'comic_scene',
  (select owner_id from games where id=p_game)
 from jsonb_array_elements(catalog) c
 where exists(select 1 from fiscal_region_reference f where f.code=c->'comic_scene'->>'region_code')
 on conflict(game_id,case_key) do nothing;
end;$$;
revoke all on function private.seed_budget_regional_cases(uuid) from public,anon,authenticated;


CREATE OR REPLACE FUNCTION public.get_budget_simulator(p_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare row_id uuid;reason text;begin
 if auth.uid() is null or not private.is_game_member(p_game_id) then raise exception 'Нет доступа к бюджетному симулятору этой игры.';end if;
 if exists(select 1 from games where id=p_game_id and status not in ('finished','archived')) and exists(select 1 from game_members m where m.game_id=p_game_id and m.user_id=auth.uid() and m.roster_archived_at is null) then perform private.ensure_budget_simulator(p_game_id);end if;
 if private.active_budget_actor(p_game_id) then
 perform private.seed_budget_cases(p_game_id);perform private.seed_budget_regional_cases(p_game_id);
 for row_id in select p.id from budget_simulator_plans p join formal_documents d on d.id=p.document_id and d.game_id=p.game_id where p.game_id=p_game_id and p.status='document' and d.status_code='published' order by d.updated_at loop
  begin perform private.apply_budget_simulator_plan(p_game_id,row_id);
  exception when others then
   get stacked diagnostics reason=MESSAGE_TEXT;
   insert into budget_simulator_ledger(game_id,kind,note,source_key) values(p_game_id,'publication_blocked',
    'Расчет '||row_id||' не применен: '||case when sqlstate='P0001' then reason else 'Проверьте связанный проект бюджета и числовые приложения.' end,'blocked:'||row_id) on conflict do nothing;
  end;
 end loop;
 for row_id in select c.id from event_cases c join event_case_outcomes o on o.case_id=c.id and o.game_id=c.game_id where c.game_id=p_game_id and c.case_key like 'budget-risk-%' and not exists(select 1 from budget_simulator_ledger l where l.game_id=p_game_id and l.source_key='outcome:'||c.id) loop perform private.apply_budget_financial_outcome(p_game_id,row_id);end loop;
 perform private.dispatch_budget_risks(p_game_id);
 end if;
 return jsonb_build_object('state',(select to_jsonb(s) from budget_simulator_state s where game_id=p_game_id),
 'plans',(select coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc),'[]') from (select pl.*,d.registry_no from budget_simulator_plans pl left join formal_documents d on d.id=pl.document_id where pl.game_id=p_game_id order by pl.updated_at desc limit 30)p),
 'requests',(select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc),'[]') from (select r.*,f.name region_name,c.title event_title from budget_transfer_requests r join fiscal_region_reference f on f.code=r.region_code left join event_cases c on c.id=r.event_case_id and c.game_id=r.game_id where r.game_id=p_game_id)r),
 'regional_events',(select coalesce(jsonb_agg(to_jsonb(e) order by e.region_code,e.title),'[]'::jsonb) from (
  select c.id,c.title,c.situation,c.comic_scene->>'region_code' region_code,c.comic_scene->'budget_request' budget_request,
   case when exists(select 1 from event_case_outcomes o where o.case_id=c.id and o.game_id=c.game_id) then 'resolved'
    when exists(select 1 from event_assignments a where a.case_id=c.id and a.game_id=c.game_id) then 'assigned' else 'ready' end status,
   exists(select 1 from event_assignments a where a.case_id=c.id and a.game_id=c.game_id and a.recipient_id=auth.uid()) assigned
  from event_cases c where c.game_id=p_game_id and c.status='ready'
   and jsonb_typeof(c.comic_scene->'budget_request')='object'
   and exists(select 1 from fiscal_region_reference f where f.code=c.comic_scene->>'region_code')
   and (c.case_key like 'budget-region-2026-%' or private.is_game_teacher(p_game_id) or private.can_prepare_budget(p_game_id)
    or exists(select 1 from event_assignments a where a.case_id=c.id and a.game_id=c.game_id and a.recipient_id=auth.uid()))
 ) e),
 'contracts',(select coalesce(jsonb_agg(to_jsonb(c) order by c.maturity_month,c.created_at),'[]') from budget_finance_contracts c where c.game_id=p_game_id),
 'ledger',(select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at desc,l.id desc),'[]') from (select * from budget_simulator_ledger where game_id=p_game_id order by created_at desc,id desc limit 80)l),
 'can_prepare',private.can_prepare_budget(p_game_id),'can_request',private.can_request_budget_transfer(p_game_id),
 'event_count',(select count(*) from event_assignments a join event_cases c on c.id=a.case_id where a.game_id=p_game_id and a.status in ('pending','accepted') and c.case_key like 'budget-%' and (a.recipient_id=auth.uid() or private.is_game_teacher(p_game_id))));
end$function$;

-- A budget is submitted collegially by Government before its Duma registration.
-- Only this budget step is added; existing voting engines and all other workflows are unchanged.
create or replace function private.formal_vote_required(p_document public.formal_documents) returns boolean
language sql immutable set search_path=public,private,pg_temp as $$
 select p_document.status_code='president_veto'
 or (p_document.workflow_key in ('bill','budget') and p_document.status_code in ('reading1','reading2','reading3'))
 or (p_document.workflow_key in ('government_act','gd_resolution','sf_resolution') and p_document.status_code='agenda')
 or (p_document.workflow_key='municipal_act' and p_document.status_code='meeting')
 or (p_document.doc_type='federal_budget' and p_document.workflow_key='budget'
  and (p_document.status_code='government' or p_document.status_code='revision' and p_document.current_owner_key='government' and p_document.current_step=1));
$$;
revoke all on function private.formal_vote_required(public.formal_documents) from public,anon,authenticated;

create function private.guard_budget_government_ballot() returns trigger
language plpgsql security definer set search_path=public,private,pg_temp as $$
declare d formal_documents%rowtype;weights jsonb;eligible numeric;
begin
 if new.formal_document_id is null then return new;end if;
 select * into d from formal_documents where id=new.formal_document_id and game_id=new.game_id;
 if d.id is null or d.doc_type<>'federal_budget' or d.workflow_key<>'budget' then return new;end if;
 if nullif(trim(coalesce(new.group_name,'')),'') is not null or nullif(trim(coalesce(current_setting('app.vote_group',true),'')),'') is not null then raise exception 'Бюджет голосуется полным составом соответствующего органа: учебная группа не сокращает состав.';end if;
 if d.status_code='president_veto' then
  perform private.lock_budget_actor(d.game_id);
  if new.voting_mode is distinct from 'mandate' or new.institution_key is distinct from 'gd'
   or new.procedure_key is distinct from 'presidential_veto_override' or new.formal_step_code is distinct from d.status_code
   or new.quorum_kind is distinct from 'fraction' or new.quorum_value is distinct from 0.5
   or new.majority_kind is distinct from 'eligible_fraction' or abs(new.majority_value-2::numeric/3)>0.00000001
   or new.allow_abstain is distinct from true or new.tie_breaker_chair is distinct from false
   or new.pass_transition is distinct from 'advance' or new.fail_transition is distinct from 'reject'
   or new.status is distinct from 'open' or new.created_by is distinct from auth.uid() then raise exception 'Преодоление вето по бюджету требует установленного голосования Государственной Думы.';end if;
  select coalesce(jsonb_object_agg(w.key,w.value),'{}'::jsonb) into weights from jsonb_each(coalesce(new.electorate_snapshot->'weights','{}'::jsonb)) w
   where exists(select 1 from game_members m where m.game_id=new.game_id and m.user_id::text=w.key and m.roster_archived_at is null);
  new.electorate_snapshot:=new.electorate_snapshot||jsonb_build_object('weights',weights,'eligible',450);
  return new;
 end if;
 if d.status_code in ('reading1','reading2','reading3') then
  perform private.lock_budget_actor(d.game_id);
  if new.voting_mode is distinct from 'mandate' or new.institution_key is distinct from 'gd'
   or new.procedure_key is distinct from 'budget_'||d.status_code or new.formal_step_code is distinct from d.status_code
   or new.quorum_kind is distinct from 'fraction' or new.quorum_value is distinct from 0.5
   or new.majority_kind is distinct from 'eligible_majority' or new.majority_value is distinct from 0.5
   or new.allow_abstain is distinct from true or new.tie_breaker_chair is distinct from false
   or new.pass_transition is distinct from 'advance' or new.fail_transition is distinct from (case when d.status_code='reading1' then 'none' else 'reject' end)
   or new.status is distinct from 'open' or new.created_by is distinct from auth.uid() then raise exception 'Чтение бюджета требует голосования Государственной Думы большинством от полного состава при зарегистрированном кворуме.';end if;
  select coalesce(jsonb_object_agg(w.key,w.value),'{}'::jsonb) into weights from jsonb_each(coalesce(new.electorate_snapshot->'weights','{}'::jsonb)) w
   where exists(select 1 from game_members m where m.game_id=new.game_id and m.user_id::text=w.key and m.roster_archived_at is null);
  new.electorate_snapshot:=new.electorate_snapshot||jsonb_build_object('weights',weights,'eligible',450);
  return new;
 end if;
 if not(d.status_code='government' or d.status_code='revision' and d.current_owner_key='government' and d.current_step=1) then raise exception 'На этом шаге бюджет проходит установленную процедуру реестра; произвольное голосование не заменяет её.';end if;
 perform private.lock_budget_actor(d.game_id);
 if nullif(trim(coalesce(new.group_name,'')),'') is not null or nullif(trim(coalesce(current_setting('app.vote_group',true),'')),'') is not null then raise exception 'Внесение федерального бюджета голосуется полным составом Правительства: учебная группа не сокращает состав.';end if;
 if not private.is_game_teacher(d.game_id) and not exists(select 1 from private.formal_user_roles(d.game_id,auth.uid()) r
  where r ~ '^председатель[[:space:]]+правительства([[:space:]]|$)') then raise exception 'Коллегиальное внесение бюджета открывает Председатель Правительства или преподаватель.';end if;
 if new.voting_mode is distinct from 'member' or new.institution_key is distinct from 'government'
  or new.procedure_key is distinct from 'budget_government_submission' or new.formal_step_code is distinct from d.status_code
  or new.quorum_kind is distinct from 'fraction' or new.quorum_value is distinct from 0.5
  or new.majority_kind is distinct from 'present_majority' or new.majority_value is distinct from 0.5
  or new.allow_abstain is distinct from true or new.tie_breaker_chair is distinct from true
  or new.pass_transition is distinct from 'advance' or new.fail_transition is distinct from 'return_author'
  or new.status is distinct from 'open' or new.created_by is distinct from auth.uid() then raise exception 'Для внесения бюджета требуется голосование Правительства с регистрацией, кворумом и решением по установленной процедуре.';end if;
 -- This trigger runs after the common electorate snapshot. Exclude archived
 -- actors only for this new budget ballot; other elections keep their snapshot.
 select coalesce(jsonb_object_agg(w.key,w.value),'{}'::jsonb),coalesce(sum((w.value#>>'{}')::numeric),0)
  into weights,eligible from jsonb_each(coalesce(new.electorate_snapshot->'weights','{}'::jsonb)) w
  where exists(select 1 from game_members m where m.game_id=new.game_id and m.user_id::text=w.key and m.roster_archived_at is null);
 new.electorate_snapshot:=new.electorate_snapshot||jsonb_build_object('weights',weights,'eligible',eligible);
 return new;
end;$$;
revoke all on function private.guard_budget_government_ballot() from public,anon,authenticated;
create trigger zz_guard_budget_government_ballot before insert on public.game_votes
 for each row execute function private.guard_budget_government_ballot();

create function private.guard_budget_government_submission() returns trigger
language plpgsql security definer set search_path=public,private,pg_temp as $$
begin
 if old.doc_type='federal_budget' and old.workflow_key='budget'
  and (old.status_code='government' or old.status_code='revision' and old.current_owner_key='government' and old.current_step=1)
  and new.status_code='budget_registered' and new.status_code is distinct from old.status_code then
  perform private.lock_budget_actor(old.game_id);
  if not exists(select 1 from game_votes v where v.game_id=old.game_id and v.formal_document_id=old.id
   and v.formal_step_code=old.status_code and v.institution_key='government' and v.procedure_key='budget_government_submission'
   and v.status='closed' and v.result_code='passed' and v.result_quorum_met=true
   and v.voting_mode='member' and v.majority_kind='present_majority' and v.majority_value=0.5
   and v.quorum_kind='fraction' and v.quorum_value=0.5 and v.result_present>0
   and v.result_yes>0 and v.pass_transition='advance') then raise exception 'Внесение бюджета в Государственную Думу требует принятого коллегиального решения Правительства.';end if;
 end if;
 return new;
end;$$;
revoke all on function private.guard_budget_government_submission() from public,anon,authenticated;
create trigger guard_budget_government_submission before update of status_code on public.formal_documents
 for each row execute function private.guard_budget_government_submission();


-- Boolean classification helpers are private and do not return content.
-- INVOKER guards see the SQL caller (authenticated/anon vs protected RPC owner),
-- while these helpers can classify hidden OLD/NEW links even under table RLS.
create function private.is_budget_document(p_id uuid) returns boolean
language sql stable security definer set search_path=public,private,pg_temp as $$
 select exists(select 1 from formal_documents d where d.id=p_id and (d.workflow_key='budget' or d.doc_type='federal_budget'));
$$;
create function private.is_budget_vote(p_id uuid) returns boolean
language sql stable security definer set search_path=public,private,pg_temp as $$
 select exists(select 1 from game_votes v where v.id=p_id and (v.procedure_key in ('budget_government_submission','budget_reading1','budget_reading2','budget_reading3','budget_preparation_amendment','budget_second_reading_amendment') or private.is_budget_document(v.formal_document_id)));
$$;
revoke all on function private.is_budget_document(uuid),private.is_budget_vote(uuid) from public;
grant execute on function private.is_budget_document(uuid),private.is_budget_vote(uuid) to anon,authenticated;

create function private.guard_budget_document_direct_write() returns trigger
language plpgsql security invoker set search_path='' as $$
declare guarded boolean;
begin
 guarded:=(
  (tg_op<>'INSERT' and (old.workflow_key='budget' or old.doc_type='federal_budget'))
  or (tg_op<>'DELETE' and (new.workflow_key='budget' or new.doc_type='federal_budget')));
 if guarded then
  if current_user in ('anon','authenticated') then raise exception 'Изменения бюджета проходят через защищённую процедуру реестра НПА.';end if;
  if tg_op<>'DELETE' and auth.uid() is not null then perform private.lock_budget_actor(new.game_id);end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end;$$;
revoke all on function private.guard_budget_document_direct_write() from public,anon,authenticated;
create trigger guard_budget_document_direct_write before insert or update or delete on public.formal_documents
 for each row execute function private.guard_budget_document_direct_write();

create function private.guard_budget_vote_direct_write() returns trigger
language plpgsql security invoker set search_path='' as $$
declare guarded boolean;
begin
 guarded:=(tg_op<>'INSERT' and (old.procedure_key in ('budget_government_submission','budget_reading1','budget_reading2','budget_reading3','budget_preparation_amendment','budget_second_reading_amendment') or private.is_budget_document(old.formal_document_id)))
  or (tg_op<>'DELETE' and (new.procedure_key in ('budget_government_submission','budget_reading1','budget_reading2','budget_reading3','budget_preparation_amendment','budget_second_reading_amendment') or private.is_budget_document(new.formal_document_id)));
 if guarded and current_user in ('anon','authenticated') then raise exception 'Правила, состав и результаты бюджетного голосования меняет защищённая процедура.';end if;
 if guarded and tg_op<>'DELETE' and auth.uid() is not null then perform private.lock_budget_actor(new.game_id);end if;
 return case when tg_op='DELETE' then old else new end;
end;$$;
revoke all on function private.guard_budget_vote_direct_write() from public,anon,authenticated;
create trigger guard_budget_vote_direct_write before insert or update or delete on public.game_votes
 for each row execute function private.guard_budget_vote_direct_write();

create function private.guard_budget_ballot_direct_write() returns trigger
language plpgsql security invoker set search_path='' as $$
declare guarded boolean;g uuid;
begin
 guarded:=(tg_op<>'INSERT' and private.is_budget_vote(old.vote_id)) or (tg_op<>'DELETE' and private.is_budget_vote(new.vote_id));
 if guarded then
  if current_user in ('anon','authenticated') then raise exception 'Бюджетный голос подаётся через защищённую форму голосования.';end if;
  if tg_op<>'DELETE' and auth.uid() is not null then
   select game_id into g from public.game_votes where id=new.vote_id;
   if new.voter_id is distinct from auth.uid() or not private.active_budget_actor(g) then raise exception 'Бюджетный голос подаёт действующий участник текущей игры.';end if;
  end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end;$$;
revoke all on function private.guard_budget_ballot_direct_write() from public,anon,authenticated;
create trigger guard_budget_ballot_direct_write before insert or update or delete on public.game_ballots
 for each row execute function private.guard_budget_ballot_direct_write();


-- Explicit ACLs for every introduced API/helper; existing SELECT-only RLS remains in force.
revoke all on function private.validate_budget_draft(uuid,jsonb),private.calculate_budget_simulator(uuid,jsonb),
 private.fiscal_event_outcome(),private.apply_budget_simulator_plan(uuid,uuid) from public,anon,authenticated;
revoke all on function public.save_budget_simulator(uuid,uuid,jsonb,integer),
 public.create_budget_transfer_request(uuid,text,text,numeric,numeric,text,text),
 public.create_budget_simulator_document(uuid),public.get_budget_simulator(uuid),public.start_regional_case(uuid) from public,anon;
grant execute on function public.save_budget_simulator(uuid,uuid,jsonb,integer),
 public.create_budget_transfer_request(uuid,text,text,numeric,numeric,text,text),
 public.create_budget_simulator_document(uuid),public.get_budget_simulator(uuid),public.start_regional_case(uuid) to authenticated;
notify pgrst,'reload schema';

